//! The generated `.ferris-idea/.gitignore` of a workspace (`SPEC-0069` behaviour 3): state that
//! belongs to one machine or one user stays out of version control.

use std::path::Path;

/// The first line of the generated file; while a file starts with it, the file is ours to extend.
const GENERATED_HEADER: &str = "# Machine-local Ferris IDEA state";

/// The first line older versions wrote under the product's former name (`SPEC-0356` behaviour 9).
const FORMER_GENERATED_HEADER: &str = "# Machine-local IDECraft state"; // rebrand:keep

/// Ignore rules written to `.ferris-idea/.gitignore` for state that belongs to one machine or one
/// user (`SPEC-0069` behaviours 3 and 3a). New entries go to the end, so a file generated by an
/// earlier version becomes this text when it is extended.
pub const LOCAL_STATE_IGNORE: &str = "# Machine-local Ferris IDEA state\nhistory/\nrecent-files\nagent-log.jsonl\nbreakpoints\n\
     generated-requests.http\nvitest.json\njest.json\npytest.xml\nrun/\ntool-windows.json\nbranch-favorites.toml\n\
     commit-messages.toml\nchangelists.toml\neditor-tabs.json\nterminal-sessions.json\nrun-pins.json\n\
     profiles/\ndeps/\nbrowser-profile/\nchange-sets/\n";

/// `current` with the entries of [`LOCAL_STATE_IGNORE`] it lacks appended, each on a line of its
/// own; `None` when nothing is missing. Every line of `current` stays as it is and where it is,
/// except a first line written under the product's former name, which becomes today's header.
fn extended(current: &str) -> Option<String> {
    if FORMER_GENERATED_HEADER != GENERATED_HEADER
        && let Some(rest) = current.strip_prefix(FORMER_GENERATED_HEADER)
        && (rest.is_empty() || rest.starts_with(['\n', '\r', ' ', '\t']))
    {
        let renamed = format!("{GENERATED_HEADER}{rest}");
        return Some(extended(&renamed).unwrap_or(renamed));
    }
    let missing: Vec<&str> = LOCAL_STATE_IGNORE
        .lines()
        .filter(|entry| !current.lines().any(|l| l.trim_end() == *entry))
        .collect();
    if missing.is_empty() {
        return None;
    }
    let mut text = current.to_owned();
    if !text.ends_with('\n') {
        text.push('\n');
    }
    for entry in missing {
        text.push_str(entry);
        text.push('\n');
    }
    Some(text)
}

/// Makes sure the workspace's `.ferris-idea/` exists and its generated `.gitignore` lists the
/// machine-local state: written when missing, extended by the entries it lacks while its first
/// line is still the generated comment (lines the user added stay), left alone once the user
/// replaced that line. Machine-local state stays out of version control, like the reference's
/// `.idea/.gitignore`. `false` when the folder cannot be created.
pub fn refresh_local_state_ignore(root: &Path) -> bool {
    // The folder of the product's former name moves first, so creating today's folder never
    // stands in its way (`SPEC-0356` behaviour 2).
    crate::takeover::take_over_project_folder(root);
    let dir = root.join(".ferris-idea");
    if std::fs::create_dir_all(&dir).is_err() {
        return false;
    }
    let ignore = dir.join(".gitignore");
    match std::fs::read_to_string(&ignore) {
        Ok(current) => {
            let first = current.lines().next().map(str::trim_end);
            let generated =
                first == Some(GENERATED_HEADER) || first == Some(FORMER_GENERATED_HEADER);
            if generated && let Some(text) = extended(&current) {
                let _ = std::fs::write(ignore, text);
            }
        }
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            let _ = std::fs::write(ignore, LOCAL_STATE_IGNORE);
        }
        // A file that cannot be read is not replaced.
        Err(_) => {}
    }
    true
}

#[cfg(test)]
mod tests {
    use super::*;

    /// SPEC-0335 AK-4 (behaviour 19): the changelists are machine-local state.
    #[test]
    fn the_generated_ignore_file_lists_the_changelists() {
        assert!(LOCAL_STATE_IGNORE.lines().any(|l| l == "changelists.toml"));
        assert!(
            LOCAL_STATE_IGNORE
                .lines()
                .any(|l| l == "commit-messages.toml")
        );
        let dir =
            std::env::temp_dir().join(format!("ferris-idea-local-state-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        assert!(refresh_local_state_ignore(&dir));
        let ignore = dir.join(".ferris-idea/.gitignore");
        assert_eq!(
            std::fs::read_to_string(&ignore).unwrap(),
            LOCAL_STATE_IGNORE
        );
        // A file the user changed is left alone.
        std::fs::write(&ignore, "mine\n").unwrap();
        assert!(refresh_local_state_ignore(&dir));
        assert_eq!(std::fs::read_to_string(&ignore).unwrap(), "mine\n");
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// SPEC-0069 AK-6 (v4, behaviour 3a): the window state of one user and the caches are
    /// listed.
    #[test]
    fn the_generated_ignore_file_lists_window_state_and_caches() {
        for entry in [
            "editor-tabs.json",
            "terminal-sessions.json",
            "run-pins.json",
            "profiles/",
            "deps/",
            "browser-profile/",
        ] {
            assert!(LOCAL_STATE_IGNORE.lines().any(|l| l == entry), "{entry}");
        }
        assert_eq!(LOCAL_STATE_IGNORE.lines().next(), Some(GENERATED_HEADER));
    }

    /// SPEC-0069 AK-6 (v4, behaviour 3a): a generated file of an earlier version gets the
    /// missing entries appended; lines the user added stay; a file of the user's is left alone.
    #[test]
    fn an_earlier_generated_ignore_file_is_extended_and_keeps_the_users_lines() {
        let dir = std::env::temp_dir().join(format!(
            "ferris-idea-local-state-extend-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(dir.join(".ferris-idea")).unwrap();
        let ignore = dir.join(".ferris-idea/.gitignore");

        // The file as the version before wrote it becomes the current text.
        let (earlier, _) = LOCAL_STATE_IGNORE.split_once("editor-tabs.json\n").unwrap();
        assert!(earlier.ends_with("changelists.toml\n"));
        std::fs::write(&ignore, earlier).unwrap();
        assert!(refresh_local_state_ignore(&dir));
        assert_eq!(
            std::fs::read_to_string(&ignore).unwrap(),
            LOCAL_STATE_IGNORE
        );

        // Lines of the user below the comment, the last one without a line break.
        let mine = format!("{earlier}scratch/\n# keep\n!deps/keep.txt");
        std::fs::write(&ignore, &mine).unwrap();
        assert!(refresh_local_state_ignore(&dir));
        let text = std::fs::read_to_string(&ignore).unwrap();
        assert!(text.starts_with(&mine), "{text}");
        assert_eq!(
            text[mine.len()..].lines().collect::<Vec<_>>(),
            [
                "",
                "editor-tabs.json",
                "terminal-sessions.json",
                "run-pins.json",
                "profiles/",
                "deps/",
                "browser-profile/",
                "change-sets/"
            ]
        );
        // Nothing is missing any more: the file stays byte for byte.
        assert!(refresh_local_state_ignore(&dir));
        assert_eq!(std::fs::read_to_string(&ignore).unwrap(), text);

        // Without the generated comment the file is the user's.
        std::fs::write(&ignore, "# mine\nhistory/\n").unwrap();
        assert!(refresh_local_state_ignore(&dir));
        assert_eq!(
            std::fs::read_to_string(&ignore).unwrap(),
            "# mine\nhistory/\n"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// SPEC-0356 AK-7 (behaviour 9): a generated file written under the product's former name is
    /// still recognised, gets today's first line and the missing entries; the user's lines stay.
    #[test]
    fn a_file_generated_under_the_former_name_is_still_ours() {
        let dir = std::env::temp_dir().join(format!(
            "ferris-idea-local-state-former-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(dir.join(".ferris-idea")).unwrap();
        let ignore = dir.join(".ferris-idea/.gitignore");
        let (_, entries) = LOCAL_STATE_IGNORE.split_once('\n').unwrap();
        let (earlier, _) = entries.split_once("editor-tabs.json\n").unwrap();
        std::fs::write(
            &ignore,
            format!("{FORMER_GENERATED_HEADER}\n{earlier}scratch/\n"),
        )
        .unwrap();
        assert!(refresh_local_state_ignore(&dir));
        let text = std::fs::read_to_string(&ignore).unwrap();
        assert_eq!(text.lines().next(), Some(GENERATED_HEADER), "{text}");
        assert!(text.contains("\nscratch/\n"), "{text}");
        for entry in LOCAL_STATE_IGNORE.lines() {
            assert_eq!(
                text.lines().filter(|l| *l == entry).count(),
                1,
                "{entry}: {text}"
            );
        }
        let _ = std::fs::remove_dir_all(&dir);
    }
}
